88	pub async fn was_event_emitted(
89	    provider: &DynProvider<Ethereum>,
90	    address: Address,
91	    event_sig: &str,
92	    epoch: u64,
93	) -> bool {
94	    let current_block = match provider.get_block_number().await {
95	        Ok(b) => b,
96	        Err(_) => return false,
97	    };
98	    let from_block = current_block.saturating_sub(500);
99	
100	    let sig = alloy::primitives::keccak256(event_sig);
101	    let filter = Filter::new()
102	        .address(address)
103	        .event_signature(sig)
104	        .from_block(from_block)
105	        .to_block(from_block + 1000);
106	
107	    match provider.get_logs(&filter).await {
108	        Ok(logs) => logs.iter().any(|log| {
109	            log.topics().get(1)
110	                .map(|t| U256::from_be_bytes(t.0).to::<u64>() == epoch)
111	                .unwrap_or(false)
112	        }),
113	        Err(_) => false,
114	    }
115	}
