117	/// The lowest nonce this account has broadcast but not had confirmed, if any.
118	///
119	/// A fee bump only helps the transaction sitting at this nonce; anything numbered
120	/// above it cannot be mined until that one clears, so bumping those overpays without
121	/// unblocking anything.
122	///
123	/// Approximate by nature - mempool contents are node-local and `FallbackService` races
124	/// several transports - so this is used only to avoid pointless bumps, never as the
125	/// safety mechanism. Preventing a duplicate send is the pinned nonce's job, and that
126	/// never consults the mempool.
127	pub async fn blocking_nonce(provider: &DynProvider<Ethereum>, address: Address) -> Option<u64> {
128	    let confirmed = provider.get_transaction_count(address).latest().await.ok()?;
129	    let pending = provider.get_transaction_count(address).pending().await.ok()?;
130	    (pending > confirmed).then_some(confirmed)
131	}
