133	/// Send `call`, or replace this task's in-flight transaction with a fee-bumped one at
134	/// the same nonce.
135	///
136	/// The nonce is pinned on every send, not just replacements. Pinning bypasses alloy's
137	/// `NonceFiller` (its `status()` returns `Finished` once a nonce is set), which is
138	/// correct for a replacement - it reuses a slot rather than claiming a new one - and
139	/// on a first send it means the nonce is known *before* broadcasting. Reading it back
140	/// afterwards would be unreliable: a node that has not yet seen the transaction answers
141	/// null, and losing the nonce would let the next cycle send a duplicate, which is the
142	/// exact failure this function exists to prevent.
143	pub async fn send_or_replace<P, D>(
144	    call: alloy::contract::CallBuilder<P, D, Ethereum>,
145	    provider: &DynProvider<Ethereum>,
146	    wallet_address: Address,
147	    task_store: &Arc<Mutex<TaskStore>>,
148	    epoch: u64,
149	    action: &str,
150	    route_name: &str,
151	) -> Result<(), Box<dyn std::error::Error + Send + Sync>>
152	where
153	    P: Provider<Ethereum>,
154	    D: alloy::contract::CallDecoder,
155	{
156	    let key = pending_key(action, epoch);
157	    let market = provider.estimate_eip1559_fees().await?;
158	
159	    // Bound to a local so the `MutexGuard` is dropped here rather than being held
160	    // across the awaits below, which would make this future non-`Send`.
161	    let existing = task_store.lock().unwrap().get_pending_tx(&key);
162	
163	    let (nonce, max_fee, priority_fee) = match existing {
164	        Some(previous) => {
165	            let nonce = previous.nonce;
166	            if let Some(blocking) = blocking_nonce(provider, wallet_address).await {
167	                if blocking != nonce {
168	                    info!(logger = "Task", route = route_name, action, nonce, blocking, "Queued behind an earlier nonce, waiting");
169	                    return Err("PendingReplacement".into());
170	                }
171	            }
172	            match (
173	                crate::bumped_fee(previous.max_fee, market.max_fee_per_gas),
174	                crate::bumped_fee(previous.priority_fee, market.max_priority_fee_per_gas),
175	            ) {
176	                (Some(max_fee), Some(priority_fee)) => {
177	                    info!(logger = "Task", route = route_name, action, nonce, max_fee, "Replacing pending tx with a higher fee");
178	                    (nonce, max_fee, priority_fee)
179	                }
180	                _ => {
181	                    warn!(logger = "Task", route = route_name, action, nonce, "Fee ceiling reached, holding rather than bumping further");
182	                    return Err("PendingReplacement".into());
183	                }
184	            }
185	        }
186	        None => {
187	            let nonce = provider.get_transaction_count(wallet_address).pending().await?;
188	            (nonce, market.max_fee_per_gas, market.max_priority_fee_per_gas)
189	        }
190	    };
191	
192	    task_store.lock().unwrap().set_pending_tx(&key, nonce, max_fee, priority_fee);
193	
194	    let sent = call
195	        .nonce(nonce)
196	        .max_fee_per_gas(max_fee)
197	        .max_priority_fee_per_gas(priority_fee)
198	        .send()
199	        .await;
200	
201	    let pending = match sent {
202	        Ok(pending) => pending,
203	        Err(e) => {
204	            let msg = e.to_string();
205	            if msg.contains("nonce too low") {
206	                info!(logger = "Task", route = route_name, action, nonce, "Nonce already consumed, deferring to on-chain checks");
207	                task_store.lock().unwrap().clear_pending_tx(&key);
208	                return Err("NonceConsumed".into());
209	            }
210	            if msg.contains("replacement transaction underpriced") {
211	                warn!(logger = "Task", route = route_name, action, nonce, "Replacement underpriced, bumping further next cycle");
212	                return Err("PendingReplacement".into());
213	            }
214	            // Anything else may or may not have reached a mempool, so the record stays:
215	            // a stale one is harmless, a lost one risks a duplicate.
216	            return send_tx(Err(e), action, route_name).await;
217	        }
218	    };
219	
220	    match pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await {
221	        Ok(receipt) => {
222	            task_store.lock().unwrap().clear_pending_tx(&key);
223	            if !receipt.status() {
224	                return Err(format!("[{}] {} reverted", route_name, action).into());
225	            }
226	            info!(logger = "Task", route = route_name, action, "Transaction succeeded");
227	            Ok(())
228	        }
229	        Err(e) => {
230	            warn!(logger = "Task", route = route_name, action, nonce, "Receipt not seen ({e}), will replace next cycle");
231	            Err("PendingReplacement".into())
232	        }
233	    }
234	}
