236	pub async fn send_tx(
237	    result: Result<PendingTransactionBuilder<Ethereum>, ContractError>,
238	    action: &str,
239	    route_name: &str,
240	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
241	    match result {
242	        Ok(pending) => {
243	            let receipt = pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await?;
244	            if !receipt.status() {
245	                return Err(format!("[{}] {} reverted", route_name, action).into());
246	            }
247	            info!(logger = "Task", route = route_name, action, "Transaction succeeded");
248	            Ok(())
249	        }
250	        Err(e) => {
251	            let err_msg = e.to_string();
252	            match decode_revert_reason(&err_msg) {
253	                Some(reason) => {
254	                    error!(logger = "Task", route = route_name, action, reason = reason.as_str(), "Transaction reverted");
255	                    Err(format!("[{}] {} reverted: {}", route_name, action, reason).into())
256	                }
257	                None => Err(e.into()),
258	            }
259	        }
260	    }
261	}
