361	pub struct ClaimStore {
362	    path: PathBuf,
363	}
364	
365	impl ClaimStore {
366	    pub fn new(path: impl Into<PathBuf>) -> Self {
367	        Self { path: path.into() }
368	    }
369	
370	    fn load_all(&self) -> Vec<ClaimData> {
371	        match fs::read_to_string(&self.path) {
372	            Ok(contents) => serde_json::from_str(&contents).expect("Failed to parse claims file - data corrupted"),
373	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
374	            Err(e) => panic!("Failed to read claims file: {}", e),
375	        }
376	    }
377	
378	    fn save_all(&self, claims: &[ClaimData]) {
379	        if let Some(parent) = self.path.parent() {
380	            fs::create_dir_all(parent).expect("Failed to create claims directory");
381	        }
382	        let contents = serde_json::to_string_pretty(claims).expect("Failed to serialize claims");
383	        fs::write(&self.path, contents).expect("Failed to write claims file");
384	    }
385	
386	    pub fn store(&self, claim: ClaimData) {
387	        let mut claims = self.load_all();
388	        let existing = claims.iter().filter(|c| c.epoch == claim.epoch).count();
389	        if existing > 0 {
390	            panic!("Duplicate claim for epoch {} - this should never happen", claim.epoch);
391	        }
392	        claims.push(claim);
393	        self.save_all(&claims);
394	    }
395	
396	    pub fn update<F>(&self, epoch: u64, f: F)
397	    where
398	        F: FnOnce(&mut ClaimData),
399	    {
400	        let mut claims = self.load_all();
401	        let claim = claims.iter_mut().find(|c| c.epoch == epoch);
402	        match claim {
403	            Some(c) => {
404	                f(c);
405	                self.save_all(&claims);
406	            }
407	            None => panic!("Cannot update claim for epoch {} - not found", epoch),
408	        }
409	    }
410	
411	    pub fn get(&self, epoch: u64) -> ClaimData {
412	        let claims = self.load_all();
413	        let matches: Vec<_> = claims.into_iter().filter(|c| c.epoch == epoch).collect();
414	        match matches.len() {
415	            0 => panic!("No claim found for epoch {}", epoch),
416	            1 => matches.into_iter().next().unwrap(),
417	            n => panic!("Multiple claims ({}) for epoch {} - impossible state", n, epoch),
418	        }
419	    }
420	
421	    pub fn get_claim(&self, epoch: u64) -> Claim {
422	        let c = self.get(epoch);
423	        Claim {
424	            stateRoot: c.state_root,
425	            claimer: c.claimer,
426	            timestampClaimed: c.timestamp_claimed,
427	            timestampVerification: c.timestamp_verification,
428	            blocknumberVerification: c.blocknumber_verification,
429	            honest: match c.honest.as_str() {
430	                "Claimer" => Party::Claimer,
431	                "Challenger" => Party::Challenger,
432	                _ => Party::None,
433	            },
434	            challenger: c.challenger,
435	        }
436	    }
437	
438	    pub fn remove(&self, epoch: u64) {
439	        let mut claims = self.load_all();
440	        claims.retain(|c| c.epoch != epoch);
441	        self.save_all(&claims);
442	    }
443	
444	    pub fn has_state_root_in_recent_claims(&self, state_root: FixedBytes<32>, since_timestamp: u32) -> bool {
445	        let claims = self.load_all();
446	        claims.iter().any(|c| c.state_root == state_root && c.timestamp_claimed >= since_timestamp)
447	    }
448	
449	    pub fn exists(&self, epoch: u64) -> bool {
450	        self.load_all().iter().any(|c| c.epoch == epoch)
451	    }
452	}
