218	    #[test]
219	    fn empty_cache_seeds_zero() {
220	        let cache = AnswerCache::new();
221	        assert_eq!(cache.seed(0), 0);
222	        assert_eq!(cache.seed(100), 0);
223	        assert_eq!(cache.seed(u64::MAX), 0);
224	    }
225	
226	    #[test]
227	    fn cache_seeds_equal_or_later_target() {
228	        let cache = AnswerCache::new();
229	        cache.update(100, 50);
230	        // Same target: the previous answer is exactly the answer.
231	        assert_eq!(cache.seed(100), 50);
232	        // Later target: monotonic timestamps mean the answer can only move up, so 50
233	        // is still a true lower bound.
234	        assert_eq!(cache.seed(200), 50);
235	    }
236	
237	    #[test]
238	    fn cache_refuses_earlier_target() {
239	        let cache = AnswerCache::new();
240	        cache.update(100, 50);
241	        // Block 50 is only proven to be <= the answer for targets >= 100. For an
242	        // earlier target it could sit *above* the true answer, and an over-high `lo`
243	        // would silently skip real blocks at the finality call sites.
244	        assert_eq!(cache.seed(50), 0);
245	        assert_eq!(cache.seed(99), 0);
246	    }
247	
248	    #[test]
249	    fn cache_update_is_a_ratchet() {
250	        let cache = AnswerCache::new();
251	        cache.update(200, 90);
252	        // An older/smaller-target update arriving late (two concurrent epochs finishing
253	        // out of order) must not regress the cache.
254	        cache.update(100, 40);
255	        // Still refuses anything below the ratcheted target...
256	        assert_eq!(cache.seed(150), 0);
257	        assert_eq!(cache.seed(199), 0);
258	        // ...and still hands back the block for the ratcheted target and beyond.
259	        assert_eq!(cache.seed(200), 90);
260	        assert_eq!(cache.seed(250), 90);
261	    }
262	
263	    #[test]
264	    fn finalized_floor_rejects_head_at_or_past_target() {
265	        // Finalized head already past the target: its block number may exceed the true
266	        // answer, so it must never be used as a lower bound.
267	        assert_eq!(finalized_floor(300, 900, 200), 0);
268	        assert_eq!(finalized_floor(201, 900, 200), 0);
269	        // Exactly at the target is rejected too: on a chain with non-decreasing (not
270	        // strictly increasing) timestamps, an earlier block can carry the same second.
271	        assert_eq!(finalized_floor(200, 900, 200), 0);
272	    }
273	
274	    #[test]
275	    fn finalized_floor_accepts_head_behind_target() {
276	        // Finalized head strictly behind the target: provably < the answer.
277	        assert_eq!(finalized_floor(100, 900, 200), 900);
278	        assert_eq!(finalized_floor(199, 900, 200), 900);
279	    }
280	
281	    #[test]
282	    fn pick_seed_prefers_the_cache() {
283	        // Cache usable: taken even though the finalized floor would also apply. The two
284	        // are never combined - picking the larger of them would not be provably safe.
285	        assert_eq!(pick_seed(50, Some((100, 900)), 200), 50);
286	        // ...and taken even when the finalized head is past the target and unusable.
287	        assert_eq!(pick_seed(50, Some((300, 900)), 200), 50);
288	    }
289	
290	    #[test]
291	    fn pick_seed_falls_back_to_finalized_when_cache_is_empty() {
292	        assert_eq!(pick_seed(0, Some((100, 900)), 200), 900);
293	    }
294	
295	    #[test]
296	    fn pick_seed_is_zero_when_neither_source_is_usable() {
297	        // Cache empty and finalized head past the target.
298	        assert_eq!(pick_seed(0, Some((300, 900)), 200), 0);
299	        // Cache empty and no finalized block at all (RPC error, or a node that does not
300	        // serve the tag - Anvil devnets among them).
301	        assert_eq!(pick_seed(0, None, 200), 0);
302	    }
303	
304	    /// Mirrors the "first block at or after `target_ts`" search in
305	    /// `find_block_by_timestamp_from` (lib.rs), including its head clamp and its
306	    /// `lo.min(latest)` guard, so the seeding rules above can be checked against real
307	    /// search behaviour without a provider. `timestamps[n]` is block `n`'s timestamp.
308	    fn model_search(timestamps: &[u64], target_ts: u64, lo: u64) -> u64 {
309	        let latest_num = (timestamps.len() - 1) as u64;
310	        if target_ts >= timestamps[latest_num as usize] {
311	            return latest_num;
312	        }
313	        let mut lo = lo.min(latest_num);
314	        let mut hi = latest_num;
315	        while lo < hi {
316	            let mid = lo + (hi - lo) / 2;
317	            if timestamps[mid as usize] < target_ts {
318	                lo = mid + 1;
319	            } else {
320	                hi = mid;
321	            }
322	        }
323	        lo
324	    }
325	
326	    /// Ethereum-like: timestamps strictly increase.
327	    fn l1_chain() -> Vec<u64> {
328	        (0..64u64).map(|i| 1_000 + 12 * i).collect()
329	    }
330	
331	    /// Arbitrum-like: timestamps are non-decreasing, three blocks per second.
332	    fn l2_chain() -> Vec<u64> {
333	        (0..48u64).map(|i| 1_000 + i / 3).collect()
334	    }
