1	use alloy::providers::Provider;
2	use std::sync::{Arc, Mutex};
3	use tokio::time::{sleep, Duration};
4	use tracing::{info, warn};
5	
6	use crate::config::{Route, ValidatorConfig};
7	use crate::tasks;
8	use crate::tasks::{Task, TaskKind, TaskStore, ClaimStore};
9	
10	const POLL_INTERVAL: Duration = Duration::from_secs(15);
11	
12	pub struct TaskDispatcher {
13	    config: ValidatorConfig,
14	    route: Route,
15	    task_store: Arc<Mutex<TaskStore>>,
16	    claim_store: Arc<Mutex<ClaimStore>>,
17	}
18	
19	impl TaskDispatcher {
20	    pub fn new(
21	        config: ValidatorConfig,
22	        route: Route,
23	        task_store: Arc<Mutex<TaskStore>>,
24	        claim_store: Arc<Mutex<ClaimStore>>,
25	    ) -> Self {
26	        Self {
27	            config,
28	            route,
29	            task_store,
30	            claim_store,
31	        }
32	    }
33	
34	    pub async fn run(&self) {
35	        loop {
36	            self.process_pending().await;
37	            sleep(POLL_INTERVAL).await;
38	        }
39	    }
40	
41	    pub async fn process_pending(&self) {
42	        if !self.task_store.lock().unwrap().is_on_sync() {
43	            return;
44	        }
45	
46	        let state = self.task_store.lock().unwrap().load();
47	
48	        let now = match self.route.outbox_provider.get_block_by_number(Default::default()).await {
49	            Ok(Some(block)) => block.header.timestamp,
50	            _ => {
51	                warn!(logger = "Dispatcher", route = self.route.name, "Failed to get latest block, retrying next cycle");
52	                return;
53	            }
54	        };
55	
56	        let ready: Vec<Task> = state
57	            .tasks
58	            .iter()
59	            .filter(|t| now >= t.execute_after)
60	            .cloned()
61	            .collect();
62	
63	        if ready.is_empty() {
64	            return;
65	        }
66	
67	        info!(logger = "Dispatcher", route = self.route.name, count = ready.len(), "Processing ready tasks");
68	
69	        for task in ready {
70	            info!(logger = "Dispatcher", route = self.route.name, task = task.kind.name(), epoch = task.epoch, "Executing task");
71	            let success = self.execute_task(&task, now).await;
72	            if success {
73	                info!(logger = "Dispatcher", route = self.route.name, task = task.kind.name(), epoch = task.epoch, "Completed task");
74	                self.task_store.lock().unwrap().remove_task(&task);
75	            }
76	        }
77	    }
78	
79	    /// Returns whether the task is finished with. `true` makes the caller call
80	    /// `remove_task`, which matches on `(epoch, kind)` only - so an arm that rescheduled
81	    /// the task must return `false`, or the reschedule is undone by the removal.
82	    async fn execute_task(&self, task: &Task, current_timestamp: u64) -> bool {
83	        let epoch = task.epoch;
84	        let wallet_address = self.config.wallet.default_signer().address();
85	        match &task.kind {
86	            TaskKind::SaveSnapshot => {
87	                tasks::save_snapshot::execute(&self.route, &self.task_store).await.is_ok()
88	            }
89	            TaskKind::Claim { .. } => {
90	                tasks::claim::execute(
91	                    &self.config,
92	                    &self.route,
93	                    epoch,
94	                    &self.claim_store,
95	                    current_timestamp,
96	                    &self.task_store,
97	                ).await.is_ok()
98	            }
99	            TaskKind::ValidateClaim => {
100	                match tasks::validate_claim::execute(
101	                    &self.config,
102	                    &self.route,
103	                    epoch,
104	                    &self.claim_store,
105	                    current_timestamp,
106	                    &self.task_store,
107	                ).await {
108	                    Ok(_) => true,
109	                    Err(e) if e.to_string() == "EpochNotFinalized" => {
110	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
111	                        true
112	                    }
113	                    Err(_) => false,
114	                }
115	            }
116	            TaskKind::ReconcileClaim => {
117	                match tasks::reconcile_claim::execute(
118	                    &self.config,
119	                    &self.route,
120	                    epoch,
121	                    &self.claim_store,
122	                    &self.task_store,
123	                    current_timestamp,
124	                    wallet_address,
125	                ).await {
126	                    // Reconciliation is only "done" when the claim is settled; anything
127	                    // still worth watching comes back as ReconcilePending.
128	                    Ok(_) => true,
129	                    // `false` here means "not finished", which is what keeps the task in
130	                    // the queue - returning `true` after a reschedule would hand the very
131	                    // same (epoch, kind) to `remove_task` below and delete the watchdog.
132	                    Err(e) if e.to_string() == tasks::reconcile_claim::RECONCILE_PENDING => {
133	                        self.task_store.lock().unwrap().reschedule_task(
134	                            task,
135	                            current_timestamp + tasks::reconcile_claim::RECONCILE_INTERVAL_SECS,
136	                        );
137	                        false
138	                    }
139	                    Err(e) if e.to_string() == "EpochNotFinalized" => {
140	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
141	                        false
142	                    }
143	                    // An RPC failure must never retire the watchdog: keep the task where
144	                    // it is and try again next cycle.
145	                    Err(_) => false,
146	                }
147	            }
148	            TaskKind::Challenge => {
149	                match tasks::challenge::execute(&self.config, &self.route, epoch, &self.claim_store, &self.task_store).await {
150	                    Ok(_) => true,
151	                    // In flight: keep the task as-is so the next cycle replaces it.
152	                    Err(e) if e.to_string() == "PendingReplacement" => false,
153	                    Err(e) if e.to_string() == "Insufficient funds" => {
154	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
155	                        true
156	                    }
157	                    Err(e) if e.to_string() == "VerificationStarted" => {
158	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 20 * 60);
159	                        true
160	                    }
161	                    Err(e) if e.to_string().contains("Invalid claim") => {
162	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
163	                        true
164	                    }
165	                    Err(_) => false,
166	                }
167	            }
168	            TaskKind::SendSnapshot => {
169	                tasks::send_snapshot::execute(&self.route, epoch, &self.claim_store).await.is_ok()
170	            }
171	            TaskKind::StartVerification => {
172	                match tasks::start_verification::execute(&self.route, epoch, &self.claim_store, &self.task_store, wallet_address).await {
173	                    Ok(_) => true,
174	                    Err(e) if e.to_string() == "PendingReplacement" => false,
175	                    Err(e) if e.to_string().contains("Invalid claim") => {
176	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
177	                        true
178	                    }
179	                    Err(_) => false,
180	                }
181	            }
182	            TaskKind::VerifySnapshot => {
183	                match tasks::verify_snapshot::execute(&self.route, epoch, &self.claim_store, &self.task_store, wallet_address).await {
184	                    Ok(_) => true,
185	                    Err(e) if e.to_string() == "PendingReplacement" => false,
186	                    Err(e) if e.to_string().contains("Invalid claim") => {
187	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
188	                        true
189	                    }
190	                    Err(_) => false,
191	                }
192	            }
193	            TaskKind::ExecuteRelay { position, l2_sender, dest_addr, l2_block, l1_block, l2_timestamp, amount, data } => {
194	                match tasks::execute_relay::execute(
195	                    &self.config,
196	                    &self.route,
197	                    *position,
198	                    *l2_sender,
199	                    *dest_addr,
200	                    *l2_block,
201	                    *l1_block,
202	                    *l2_timestamp,
203	                    *amount,
204	                    data.clone(),
205	                    &self.task_store,
206	                    epoch,
207	                ).await {
208	                    Ok(_) => true,
209	                    // Must precede the catch-all below, or an in-flight relay gets
210	                    // pushed 30 minutes into the future instead of being replaced.
211	                    Err(e) if e.to_string() == "PendingReplacement" => false,
212	                    Err(e) if e.to_string() == "RootNotConfirmed" => {
213	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 60 * 60);
214	                        true
215	                    }
216	                    Err(_) => {
217	                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
218	                        true
219	                    }
220	                }
221	            }
222	            TaskKind::WithdrawDeposit => {
223	                tasks::withdraw_deposit::execute(&self.route, epoch, &self.claim_store).await.is_ok()
224	            }
225	        }
226	    }
227	}
