1	//! Periodic re-synchronisation of a stored claim against finalized on-chain state.
2	//!
3	//! The event-driven path is reorg-safe on reads (the indexer ignores anything within
4	//! 20 minutes of the head) but not on writes: `send_or_replace` returns on the first
5	//! confirmation and the dispatcher then drops the task. A `Challenge` task only ever
6	//! exists because `validate_claim` created one, and `validate_claim` removes itself as
7	//! soon as it has done so - so if the challenge transaction is later reorged out, the
8	//! `Challenged` event is never (re-)observed, `SendSnapshot` is never scheduled, and
9	//! nothing re-examines the claim. The fraudulent claim then verifies unopposed.
10	//!
11	//! This task closes that hole. It re-reads the outbox at the **finalized** L1 block and
12	//! compares it against the claim we have on file:
13	//!
14	//! - claim still unchallenged and our verdict says invalid -> schedule `Challenge`
15	//! - our challenge is in the finalized chain but was never indexed -> repair the claim
16	//!   record and schedule `SendSnapshot`, exactly as the `Challenged` handler would
17	//!
18	//! It never decides anything from mutable state: the claim state comes from the
19	//! `finalized` tag, and the verdict from [`finalized_state_root`], which is the same
20	//! finality-gated read `validate_claim` uses.
21	
22	use alloy::eips::BlockId;
23	use alloy::primitives::{Address, FixedBytes, U256};
24	use std::sync::{Arc, Mutex};
25	use tracing::{error, info, warn};
26	
27	use crate::config::{Route, ValidatorConfig};
28	use crate::contracts::{Claim, IVeaOutbox, Party};
29	use crate::tasks::validate_claim::finalized_state_root;
30	use crate::tasks::{was_event_emitted, ClaimData, ClaimStore, Task, TaskKind, TaskStore};
31	
32	/// How long to wait before re-examining a claim that is still worth watching.
33	///
34	/// Matches the +30min used for every other "come back when the chain has moved on"
35	/// reschedule in the dispatcher. Nothing is gained by looking sooner: the `finalized`
36	/// tag on Ethereum only advances once every ~13 minutes, the indexer's own buffer is
37	/// 20 minutes, and a challenge window is hours wide, so a 30 minute cadence still
38	/// leaves many passes before a fraudulent claim could be verified.
39	pub const RECONCILE_INTERVAL_SECS: u64 = 30 * 60;
40	
41	/// Sentinel: the claim is not settled yet, re-check it in [`RECONCILE_INTERVAL_SECS`].
42	///
43	/// Matched by `dispatcher.rs` by exact string, like every other sentinel in this crate.
44	/// `Ok(())` means the opposite - reconciliation is finished and the task is dropped.
45	pub const RECONCILE_PENDING: &str = "ReconcilePending";
46	
47	/// The claim preimage the outbox would be storing if `challenger` were the challenger.
48	///
49	/// `honest` is fixed to `None` because a claim with a verdict recorded can no longer be
50	/// challenged; [`execute`] drops out before this is reached when our record says
51	/// otherwise.
52	fn claim_preimage(stored: &ClaimData, challenger: Address) -> Claim {
53	    Claim {
54	        stateRoot: stored.state_root,
55	        claimer: stored.claimer,
56	        timestampClaimed: stored.timestamp_claimed,
57	        timestampVerification: stored.timestamp_verification,
58	        blocknumberVerification: stored.blocknumber_verification,
59	        honest: Party::None,
60	        challenger,
61	    }
62	}
63	
64	pub async fn execute(
65	    config: &ValidatorConfig,
66	    route: &Route,
67	    epoch: u64,
68	    claim_store: &Arc<Mutex<ClaimStore>>,
69	    task_store: &Arc<Mutex<TaskStore>>,
70	    current_timestamp: u64,
71	    wallet_address: Address,
72	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
73	    // Guards taken, used and dropped without crossing an await - see tasks/mod.rs.
74	    if !claim_store.lock().unwrap().exists(epoch) {
75	        info!(logger = "ReconcileClaim", route = route.name, epoch, "No claim on file, nothing to reconcile");
76	        return Ok(());
77	    }
78	    let stored = claim_store.lock().unwrap().get(epoch);
79	
80	    // Past the sync window the claim is beyond what we could reconstruct anyway, and the
81	    // whole claim -> verify -> withdraw cycle is long over. Same bound the indexer uses
82	    // to decide a claim is unrecoverable.
83	    let expiry = u64::from(stored.timestamp_claimed).saturating_add(route.settings.sync_lookback_secs);
84	    if current_timestamp >= expiry {
85	        info!(logger = "ReconcileClaim", route = route.name, epoch, "Claim is older than the sync window, ending reconciliation");
86	        return Ok(());
87	    }
88	
89	    // A verdict has been recorded, so the claim can no longer be challenged (the outbox
90	    // requires `honest == None`) and there is nothing left for us to re-create. That
91	    // verdict came from a `Verified` event the indexer only accepted once it was more
92	    // than 20 minutes old, which is the durability bar the rest of the bot works to.
93	    if stored.honest != "None" {
94	        info!(logger = "ReconcileClaim", route = route.name, epoch, honest = stored.honest.as_str(), "Claim already resolved, ending reconciliation");
95	        return Ok(());
96	    }
97	
98	    let outbox = IVeaOutbox::new(route.outbox_address, route.outbox_provider.clone());
99	
100	    let latest_hash = outbox.claimHashes(U256::from(epoch)).call().await?;
101	    if latest_hash == FixedBytes::<32>::ZERO {
102	        // Either withdrawn (the outbox deletes the hash) or the claim itself was reorged
103	        // out. Either way there is no claim to challenge, and we must not guess at one.
104	        warn!(logger = "ReconcileClaim", route = route.name, epoch, "No claim hash on the outbox, ending reconciliation");
105	        return Ok(());
106	    }
107	
108	    // The verdict-bearing read. `latest` could still be reorged away - which is the exact
109	    // failure this task exists to catch - so the claim state has to come from a block
110	    // that cannot change.
111	    let finalized_hash = outbox
112	        .claimHashes(U256::from(epoch))
113	        .block(BlockId::finalized())
114	        .call()
115	        .await?;
116	    if finalized_hash == FixedBytes::<32>::ZERO {
117	        info!(logger = "ReconcileClaim", route = route.name, epoch, "Claim not in the finalized chain yet");
118	        return Err(RECONCILE_PENDING.into());
119	    }
120	
121	    // The outbox stores only a hash, so the on-chain challenger can only be established
122	    // by reproducing the preimage. Three candidates are reconstructible: nobody
123	    // challenged, we did, or the challenger we already have on file did.
124	    let mut candidates = vec![Address::ZERO, wallet_address];
125	    if stored.challenger != Address::ZERO && !candidates.contains(&stored.challenger) {
126	        candidates.push(stored.challenger);
127	    }
128	
129	    let mut matched: Option<Address> = None;
130	    for candidate in candidates {
131	        if outbox.hashClaim(claim_preimage(&stored, candidate)).call().await? == finalized_hash {
132	            matched = Some(candidate);
133	            break;
134	        }
135	    }
136	
137	    let Some(challenger) = matched else {
138	        // Someone else's challenge, a verification we have not indexed yet, or a claim
139	        // that differs from our record. We cannot rebuild the preimage, so we cannot act
140	        // on it - wait for the indexer rather than guess.
141	        info!(logger = "ReconcileClaim", route = route.name, epoch, "Finalized claim hash matches no reconstructible claim, waiting for the indexer");
142	        return Err(RECONCILE_PENDING.into());
143	    };
144	
145	    if challenger == Address::ZERO {
146	        return reconcile_unchallenged(config, route, epoch, &stored, claim_store, task_store, current_timestamp).await;
147	    }
148	
149	    adopt_challenge(route, epoch, &stored, challenger, claim_store, task_store, current_timestamp);
150	    // A challenge in the finalized chain cannot be reorged away, so there is nothing
151	    // left to re-check.
152	    Ok(())
153	}
154	
155	/// The finalized chain says this claim is unchallenged. Re-run the verdict and, if it is
156	/// fraudulent, put a `Challenge` task back on the queue.
157	async fn reconcile_unchallenged(
158	    config: &ValidatorConfig,
159	    route: &Route,
160	    epoch: u64,
161	    stored: &ClaimData,
162	    claim_store: &Arc<Mutex<ClaimStore>>,
163	    task_store: &Arc<Mutex<TaskStore>>,
164	    current_timestamp: u64,
165	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
166	    if stored.challenger != Address::ZERO {
167	        // We recorded a challenge that is not in the finalized chain: the `Challenged`
168	        // event was reorged out. The record has to match the outbox preimage or every
169	        // state-changing call for this epoch reverts "Invalid claim.".
170	        warn!(logger = "ReconcileClaim", route = route.name, epoch, challenger = ?stored.challenger, "Recorded challenge is absent from the finalized chain, clearing it");
171	        claim_store.lock().unwrap().update(epoch, |c| {
172	            c.challenger = Address::ZERO;
173	        });
174	    }
175	
176	    // The event-driven path still owns this epoch; scheduling a second Challenge here
177	    // would only burn gas on a revert.
178	    let state = task_store.lock().unwrap().load();
179	    if state.tasks.iter().any(|t| t.epoch == epoch && matches!(t.kind, TaskKind::ValidateClaim | TaskKind::Challenge)) {
180	        info!(logger = "ReconcileClaim", route = route.name, epoch, "Challenge already queued, nothing to re-create");
181	        return Err(RECONCILE_PENDING.into());
182	    }
183	
184	    // Propagates the `EpochNotFinalized` sentinel untouched.
185	    let correct_state_root = finalized_state_root(config, route, epoch).await?;
186	
187	    if stored.state_root == correct_state_root {
188	        // Both sides of this comparison are immutable: the epoch is finalized, so the
189	        // snapshot can no longer change, and the claim matches it. There is no verdict
190	        // left to revisit.
191	        info!(logger = "ReconcileClaim", route = route.name, epoch, "Claim matches the finalized snapshot, ending reconciliation");
192	        return Ok(());
193	    }
194	
195	    // A challenge that landed in the last few hundred blocks is real but not finalized
196	    // yet, so the check above cannot see it. Re-challenging on top of it would revert.
197	    if was_event_emitted(&route.outbox_provider, route.outbox_address, "Challenged(uint256,address)", epoch).await {
198	        info!(logger = "ReconcileClaim", route = route.name, epoch, "A challenge landed recently but is not finalized yet, re-checking later");
199	        return Err(RECONCILE_PENDING.into());
200	    }
201	
202	    error!(logger = "ReconcileClaim", route = route.name, epoch, claimed = ?stored.state_root, correct = ?correct_state_root, "INVALID claim unchallenged in the finalized chain - rescheduling challenge");
203	    task_store.lock().unwrap().add_task(Task {
204	        epoch,
205	        execute_after: current_timestamp,
206	        kind: TaskKind::Challenge,
207	    });
208	
209	    // Keep watching: the replacement challenge has to reach the finalized chain too.
210	    Err(RECONCILE_PENDING.into())
211	}
212	
213	/// A challenge we did not know about is in the finalized chain. Bring the claim record
214	/// and the task queue to where the `Challenged` handler would have left them.
215	fn adopt_challenge(
216	    route: &Route,
217	    epoch: u64,
218	    stored: &ClaimData,
219	    challenger: Address,
220	    claim_store: &Arc<Mutex<ClaimStore>>,
221	    task_store: &Arc<Mutex<TaskStore>>,
222	    current_timestamp: u64,
223	) {
224	    if stored.challenger == challenger {
225	        info!(logger = "ReconcileClaim", route = route.name, epoch, "Challenge confirmed in the finalized chain, ending reconciliation");
226	        return;
227	    }
228	
229	    warn!(logger = "ReconcileClaim", route = route.name, epoch, challenger = ?challenger, "Challenge is in the finalized chain but missing from our records - repairing");
230	    claim_store.lock().unwrap().update(epoch, |c| {
231	        c.challenger = challenger;
232	    });
233	
234	    // Same invalidation the indexer applies on `Challenged` (see DESIGN_AND_RATIONALE.md).
235	    task_store.lock().unwrap().invalidate_tasks(epoch, &["ValidateClaim", "Challenge", "StartVerification", "VerifySnapshot"]);
236	
237	    let already_queued = task_store
238	        .lock()
239	        .unwrap()
240	        .load()
241	        .tasks
242	        .iter()
243	        .any(|t| t.epoch == epoch && matches!(t.kind, TaskKind::SendSnapshot));
244	    if already_queued {
245	        return;
246	    }
247	
248	    task_store.lock().unwrap().add_task(Task {
249	        epoch,
250	        execute_after: current_timestamp,
251	        kind: TaskKind::SendSnapshot,
252	    });
253	}
