1	use alloy::primitives::U256;
2	use std::sync::{Arc, Mutex};
3	use crate::config::Route;
4	use crate::contracts::{IVeaInboxArbToEth, IVeaInboxArbToGnosis};
5	use crate::tasks::{send_tx, ClaimStore};
6	
7	pub async fn execute(
8	    route: &Route,
9	    epoch: u64,
10	    claim_store: &Arc<Mutex<ClaimStore>>,
11	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
12	    let claim = claim_store.lock().unwrap().get_claim(epoch);
13	
14	    match route.name {
15	        "ARB_TO_ETH" => {
16	            let inbox = IVeaInboxArbToEth::new(route.inbox_address, route.inbox_provider.clone());
17	            send_tx(
18	                inbox.sendSnapshot(U256::from(epoch), claim).send().await,
19	                "sendSnapshot",
20	                route.name,
21	            ).await
22	        }
23	        "ARB_TO_GNOSIS" => {
24	            let inbox = IVeaInboxArbToGnosis::new(route.inbox_address, route.inbox_provider.clone());
25	            let gas_limit = U256::from(500000);
26	            send_tx(
27	                inbox.sendSnapshot(U256::from(epoch), gas_limit, claim).send().await,
28	                "sendSnapshot",
29	                route.name,
30	            ).await
31	        }
32	        _ => panic!("Unknown route: {}", route.name),
33	    }
34	}
