73	                            // so the next cycle sends fresh - not a reason to kill the route.
74	                            Err(e) if e.to_string() == "NonceConsumed" => {
75	                                warn!(logger = "EpochWatcher", route = self.route.name, epoch = prev_epoch, "Claim nonce was consumed elsewhere, retrying next cycle");
76	                            }
77	                            Err(e) if e.to_string() == "EpochNotFinalized" => {
78	                                skip_claim_until = now + 300;
79	                            }
80	                            Err(e) if e.to_string().contains("timed out") || e.to_string().contains("connection") => {
81	                            warn!(logger = "EpochWatcher", route = self.route.name, epoch = prev_epoch, "Claim RPC error: {e}, retrying next cycle");
82	                        }
83	                        Err(e) => panic!("[{}] FATAL: Failed to claim epoch {}: {}", self.route.name, prev_epoch, e),
84	                        }
85	                    }
86	                }
87	            }
88	
89	            sleep(Duration::from_secs(10)).await;
90	        }
91	    }
92	}
