82	/// Fails with a readable message if the outbox chain cannot serve `finalized`, or if it
83	/// still lags `block` - reconciliation reads claim state at that tag and nothing else.
84	async fn assert_finalized_past(provider: &impl Provider, block: u64) {
85	    let finalized = provider
