98	/// Claims `WRONG_ROOT` for the epoch just closed and returns it, leaving the chain 20+
99	/// minutes past the claim so the indexer will pick it up.
100	async fn make_fraudulent_claim(config: &ValidatorConfig) -> u64 {
101	    let route = &config.build_routes()[0];
102	    let inbox = IVeaInboxArbToEth::new(route.inbox_address, route.inbox_provider.clone());
103	    let outbox = IVeaOutboxArbToEth::new(route.outbox_address, route.outbox_provider.clone());
104	    let epoch_period: u64 = inbox.epochPeriod().call().await.unwrap().try_into().unwrap();
105	
106	    send_messages(route).await;
107	    let epoch: u64 = inbox.epochNow().call().await.unwrap().try_into().unwrap();
108	    inbox.saveSnapshot().send().await.unwrap().get_receipt().await.unwrap();
109	
110	    advance_past_epoch(&route.outbox_provider, epoch, epoch_period).await;
111	
112	    let deposit = outbox.deposit().call().await.unwrap();
113	    let receipt = outbox
114	        .claim(U256::from(epoch), WRONG_ROOT)
115	        .value(deposit)
116	        .send()
117	        .await
118	        .unwrap()
119	        .get_receipt()
120	        .await
121	        .unwrap();
122	
123	    advance_time(20 * 60 + 10).await;
124	    mine_blocks(BLOCKS_TO_FINALITY).await;
125	    assert_finalized_past(&route.outbox_provider, receipt.block_number.unwrap()).await;
126	    epoch
127	}
