138	/// The bug this task exists for: the challenge transaction confirmed once, the dispatcher
139	/// retired the `Challenge` task, and then a reorg took the transaction back out. Nothing
140	/// in the event-driven path ever looks at that claim again.
141	#[tokio::test]
142	#[serial]
143	async fn test_reconcile_recreates_challenge_lost_to_reorg() {
144	    let c = ValidatorConfig::from_env().unwrap();
145	    restore_pristine().await;
146	    let epoch = make_fraudulent_claim(&c).await;
147	    let h = harness(&c).await;
148	    let route = &c.build_routes()[0];
149	
150	    h.indexer.scan_once().await;
151	    assert!(h.has_task(epoch, "ValidateClaim"), "ValidateClaim should be scheduled");
152	    assert!(h.has_task(epoch, "ReconcileClaim"), "ReconcileClaim should be scheduled alongside it");
153	
154	    // ValidateClaim schedules the challenge and retires itself.
155	    h.dispatcher.process_pending().await;
156	    assert!(h.has_task(epoch, "Challenge"), "Challenge should be scheduled");
157	
158	    // Simulate the reorg: the challenge was broadcast, both tasks were retired, and the
159	    // chain kept no trace of it. The claim record still says unchallenged, and the outbox
160	    // still holds the original, unchallenged claim hash.
161	    h.task_store.lock().unwrap().invalidate_tasks(epoch, &["ValidateClaim", "Challenge"]);
162	    assert!(!h.has_task(epoch, "Challenge"));
163	    assert!(h.has_task(epoch, "ReconcileClaim"), "the watchdog must survive");
164	    assert!(
165	        challenged_logs(route.outbox_address, &route.outbox_provider).await.is_empty(),
166	        "no challenge should be on chain at this point"
167	    );
168	
169	    advance_time(RECONCILE_INTERVAL_SECS + 10).await;
170	    mine_blocks(BLOCKS_TO_FINALITY).await;
171	
172	    h.dispatcher.process_pending().await;
173	    assert!(
174	        h.has_task(epoch, "Challenge"),
175	        "reconciliation should re-create the Challenge task for an unchallenged fraudulent claim"
176	    );
177	
178	    h.dispatcher.process_pending().await;
179	    let logs = challenged_logs(route.outbox_address, &route.outbox_provider).await;
180	    assert!(!logs.is_empty(), "the re-created challenge did not reach the chain");
181	    assert_eq!(U256::from_be_bytes(logs[0].topics()[1].0).to::<u64>(), epoch);
182	}
