184	/// The mirror case: our challenge did land and is finalized, but the `Challenged` event
185	/// was never indexed, so the claim record still reads `challenger == 0` and no
186	/// `SendSnapshot` was ever scheduled.
187	#[tokio::test]
188	#[serial]
189	async fn test_reconcile_adopts_unindexed_challenge() {
190	    let c = ValidatorConfig::from_env().unwrap();
191	    restore_pristine().await;
192	    let epoch = make_fraudulent_claim(&c).await;
193	    let h = harness(&c).await;
194	    let route = &c.build_routes()[0];
195	
196	    h.indexer.scan_once().await;
197	    h.dispatcher.process_pending().await; // ValidateClaim -> Challenge
198	    h.dispatcher.process_pending().await; // Challenge executes
199	
200	    let logs = challenged_logs(route.outbox_address, &route.outbox_provider).await;
201	    assert!(!logs.is_empty(), "challenge should have landed");
202	    let challenge_block = logs[0].block_number.unwrap();
