123	async fn get_block_with_retry(provider: &DynProvider<Ethereum>, block_num: alloy::eips::BlockNumberOrTag) -> Block {
124	    retry_rpc_opt(std::fmt::from_fn(|f| write!(f, "get block {block_num}")), || async { provider.get_block_by_number(block_num).await }).await
125	        .unwrap_or_else(|e| panic!("Failed to get block {block_num}: {e}"))
126	        .unwrap_or_else(|| panic!("Block {block_num} not found"))
127	}
