255	    }
256	
257	    #[tokio::test(start_paused = true)]
258	    async fn succeeds_without_sleeping_when_the_first_attempt_works() {
259	        let attempts = Arc::new(Attempts::default());
260	        let a = attempts.clone();
261	        let start = Instant::now();
262	
263	        let out: Result<u64, BoxErr> = retry_rpc("healthy call", move || {
264	            let a = a.clone();
265	            async move {
266	                a.record();
267	                Ok(7)
268	            }
269	        })
270	        .await;
271	
272	        assert_eq!(out.expect("first attempt succeeds"), 7);
273	        assert_eq!(attempts.count(), 1);
274	        assert_eq!(Instant::now() - start, Duration::ZERO, "a healthy call must not be delayed");
275	    }
276	
277	    #[tokio::test(start_paused = true)]
