116	impl FaultTransport {
117	    pub fn new<F>(script: F) -> Self
118	    where
119	        F: Fn(&Call) -> Fault + Send + Sync + 'static,
120	    {
121	        Self {
122	            script: Arc::new(script),
123	            log: Arc::new(Mutex::new(Vec::new())),
124	        }
125	    }
