128	    /// builds the real single-URL provider.
129	    pub fn provider(&self) -> DynProvider<Ethereum> {
130	        let client = RpcClient::builder().transport(self.clone(), false);
131	        DynProvider::new(ProviderBuilder::new().connect_client(client))
132	    }
