139	    /// Requests served for one method.
140	    pub fn count_of(&self, method: &str) -> usize {
141	        self.methods().iter().filter(|m| *m == method).count()
142	    }
143	
144	    /// Method names in the order they were received.
145	    pub fn methods(&self) -> Vec<String> {
146	        match self.log.lock() {
147	            Ok(log) => log.clone(),
148	            // A poisoned log means some other test thread panicked; surface the data anyway
149	            // rather than turning it into a second, confusing panic.
150	            Err(poisoned) => poisoned.into_inner().clone(),
151	        }
152	    }
153	
154	    fn record(&self, method: &str, params: serde_json::Value) -> Call {
155	        // The guard is taken, used and dropped without crossing an await, matching the
156	        // convention the stores in `tasks/mod.rs` follow for `std::sync::Mutex`.
157	        let mut log = match self.log.lock() {
158	            Ok(log) => log,
159	            Err(poisoned) => poisoned.into_inner(),
160	        };
161	        let index = log.len();
162	        let method_index = log.iter().filter(|m| m.as_str() == method).count();
163	        log.push(method.to_string());
164	        drop(log);
165	
166	        Call {
167	            index,
168	            method_index,
169	            method: method.to_string(),
170	            params,
171	        }
172	    }
173	}
