175	impl Service<RequestPacket> for FaultTransport {
176	    type Response = ResponsePacket;
177	    type Error = TransportError;
178	    type Future = TransportFut<'static>;
179	
180	    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
181	        Poll::Ready(Ok(()))
182	    }
183	
184	    fn call(&mut self, req: RequestPacket) -> Self::Future {
185	        let is_batch = matches!(req, RequestPacket::Batch(_));
186	        let requests: Vec<SerializedRequest> = match req {
187	            RequestPacket::Single(r) => vec![r],
188	            RequestPacket::Batch(rs) => rs,
189	        };
190	
191	        let mut replies = Vec::with_capacity(requests.len());
192	        for r in &requests {
193	            let params = r
194	                .params()
195	                .and_then(|p| serde_json::from_str(p.get()).ok())
196	                .unwrap_or(serde_json::Value::Null);
197	            let call = self.record(r.method(), params);
198	
199	            let payload = match (self.script)(&call) {
200	                // A hang or a transport error takes down the whole packet, which is what a
201	                // real HTTP transport does too.
202	                Fault::Hang => return Box::pin(std::future::pending()),
203	                Fault::Transport(e) => return Box::pin(async move { Err(e) }),
204	                Fault::Ok(v) => ResponsePayload::Success(
205	                    serde_json::value::to_raw_value(&v)
206	                        .expect("fault script returned non-serializable JSON"),
207	                ),
208	                Fault::RpcError { code, message } => ResponsePayload::Failure(ErrorPayload {
209	                    code,
210	                    message: Cow::Owned(message),
211	                    data: None,
212	                }),
213	            };
214	            replies.push(Response {
215	                id: r.id().clone(),
216	                payload,
217	            });
218	        }
219	
220	        let packet = if is_batch {
221	            ResponsePacket::Batch(replies)
222	        } else {
223	            match replies.pop() {
224	                Some(reply) => ResponsePacket::Single(reply),
225	                None => return Box::pin(async { Err(TransportErrorKind::custom_str("empty request packet")) }),
226	            }
227	        };
228	        Box::pin(async move { Ok(packet) })
229	    }
230	}
