/// Sentinel: our transaction is mined but not durable yet. Keep the task, change nothing,
/// and come back next cycle - do **not** send anything at this nonce again.
///
/// Distinct from `"PendingReplacement"` on purpose. That one means "still in the mempool,
/// replace it with a higher fee next cycle"; this one means "already on chain, replacing
/// it would be a duplicate". Matched by exact string in `dispatcher.rs` and
/// `epoch_watcher.rs`, like every other sentinel in this crate.
pub const AWAITING_FINALITY: &str = "AwaitingFinality";

/// Sentinels meaning "this transaction is still ours": either in the mempool
/// (`PendingReplacement`) or mined but not yet durable ([`AWAITING_FINALITY`]).
///
/// A task must return these untouched instead of falling through to its "did someone else
/// do it?" checks. Those read the chain, and for a mined-but-not-durable transaction they
/// would find *our own* effect, read it as a lost race, and retire the task - which is the
/// exact hole the durability gate closes.
pub fn is_in_flight(err: &(dyn std::error::Error + Send + Sync)) -> bool {
    let msg = err.to_string();
    msg == "PendingReplacement" || msg == AWAITING_FINALITY
}

/// How durable a write has to be before [`send_or_replace`] reports success.
///
/// One confirmation is not durability: the dispatcher retires a task the moment its
/// action returns `Ok(())`, so a transaction reorged out after that confirmation is never
/// re-sent and never re-observed.
#[derive(Clone)]
pub enum Durability {
    /// One confirmation, no gate.
    ///
    /// Only for writes whose caller re-derives its own state from the chain on every
    /// cycle, so a gate here would be escaped immediately and would leave an uncleared
    /// pending record behind. `claim` is the sole case - see `tasks/claim.rs`.
    Confirmed,
    /// The sending chain's own `finalized` tag has reached the receipt's block.
    ///
    /// The bar for every settlement-chain write: Ethereum and Gnosis both finalize under
    /// their own consensus, and their `finalized` tag is exactly "cannot be reorged".
    ChainFinalized,
    /// Arbitrum L2: the receipt's block sits in a sequencer batch whose L1 posting block
    /// is finalized.
    ///
    /// An L2 block is only as durable as the L1 batch carrying it, so the raw L2
    /// `finalized` tag is not the bar here - see [`crate::finality::is_l2_block_finalized`].
    ArbitrumBatchFinalized {
        l1_provider: DynProvider<Ethereum>,
        sequencer_inbox: Option<Address>,
    },
}

impl Durability {
    /// Whether a receipt in `receipt_block` on `provider`'s chain clears this bar.
    async fn is_durable(
        &self,
        provider: &DynProvider<Ethereum>,
        receipt_block: u64,
    ) -> Result<bool, Box<dyn std::error::Error + Send + Sync>> {
        match self {
            Durability::Confirmed => Ok(true),
            Durability::ChainFinalized => {
                let finalized = provider
                    .get_block_by_number(alloy::eips::BlockNumberOrTag::Finalized)
                    .await?
                    .map(|block| block.header.number);
                Ok(block_is_finalized(receipt_block, finalized))
            }
            Durability::ArbitrumBatchFinalized { l1_provider, sequencer_inbox } => {
                crate::finality::is_l2_block_finalized(receipt_block, provider, l1_provider, *sequencer_inbox).await
            }
