    }
}

/// The settlement-chain bar: a receipt is durable once the chain's own `finalized` tag has
/// reached its block.
///
/// `None` is "the node served no finalized block" - an RPC that cannot answer is not
/// evidence of durability, so it counts as not durable and the caller waits.
const fn block_is_finalized(receipt_block: u64, finalized_block: Option<u64>) -> bool {
    match finalized_block {
        Some(finalized) => finalized >= receipt_block,
        None => false,
    }
}

/// What the chain's answer about an already-broadcast nonce means for the task.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MinedOutcome {
    /// Mined, succeeded, durable: the write is done for good.
    Settled,
    /// Mined and succeeded, but still reorgable: wait, and do not touch the nonce.
    AwaitFinality,
    /// Mined and reverted. Terminal: the nonce is spent, so a retry needs a fresh one.
    Reverted,
    /// No receipt at all - never mined, or reorged back out. Send again at the same nonce.
    Resend,
}

/// `receipt` is `None` when the chain has no receipt for the transaction we broadcast, and
/// `Some((succeeded, durable))` when it has one.
///
/// A reverted receipt is terminal whether or not it is durable: the revert consumed the
/// nonce, so there is nothing to wait for, and the caller's own post-revert checks decide
/// what happens next.
const fn mined_outcome(receipt: Option<(bool, bool)>) -> MinedOutcome {
    match receipt {
        None => MinedOutcome::Resend,
        Some((false, _)) => MinedOutcome::Reverted,
        Some((true, false)) => MinedOutcome::AwaitFinality,
        Some((true, true)) => MinedOutcome::Settled,
    }
}

