/// What the chain currently says about a transaction we broadcast.
///
/// Every uncertainty resolves to [`MinedOutcome::AwaitFinality`] rather than
/// [`MinedOutcome::Resend`]: an RPC that will not answer is not evidence that a
/// transaction is absent, and waiting another cycle is always recoverable where re-sending
/// over a mined write is not.
async fn broadcast_outcome(
    provider: &DynProvider<Ethereum>,
    hash: FixedBytes<32>,
    durability: &Durability,
    action: &str,
    route_name: &str,
) -> MinedOutcome {
    let receipt = match provider.get_transaction_receipt(hash).await {
        Ok(receipt) => receipt,
        Err(e) => {
            warn!(logger = "Task", route = route_name, action, "Could not read the receipt ({e}), waiting rather than re-sending");
            return MinedOutcome::AwaitFinality;
        }
    };

    let receipt = match receipt {
        Some(receipt) => receipt,
        // The only path that re-sends: the chain has no receipt, so the transaction either
        // never mined or was reorged back out.
        None => return MinedOutcome::Resend,
    };

    let block = match receipt.block_number {
        Some(block) => block,
        None => {
            warn!(logger = "Task", route = route_name, action, "Receipt carries no block number, waiting");
            return MinedOutcome::AwaitFinality;
        }
    };

    mined_outcome(Some((receipt.status(), is_durable(provider, durability, block, action, route_name).await)))
}

/// [`Durability::is_durable`] with the RPC failure folded in as "not durable yet".
///
/// A failed durability read must never be reported as durable: that would retire the task
/// on exactly the evidence the gate exists to demand.
async fn is_durable(
    provider: &DynProvider<Ethereum>,
    durability: &Durability,
    block: u64,
    action: &str,
    route_name: &str,
) -> bool {
    match durability.is_durable(provider, block).await {
        Ok(durable) => durable,
        Err(e) => {
            warn!(logger = "Task", route = route_name, action, block, "Durability check failed ({e}), treating as not final");
            false
        }
    }
}

