pub fn set_pending_tx(&self, key: &str, nonce: u64, max_fee: u128, priority_fee: u128) {
    info!(logger = "TaskStore", route = self.label().as_str(), key, nonce, "Recording pending tx");
    let mut state = self.load();
    state.pending_txs.insert(key.to_string(), PendingTx { nonce, max_fee, priority_fee, tx_hash: None });
    self.save(&state);
}

/// Attach the hash of the transaction just broadcast at this key's nonce.
///
/// Written as a second step rather than as part of [`TaskStore::set_pending_tx`]
/// because the hash only exists after the send, while the nonce has to be on disk
/// before it. A replacement overwrites the hash: the record always describes the
/// latest attempt at that nonce.
pub fn set_pending_tx_hash(&self, key: &str, hash: FixedBytes<32>) {
    let mut state = self.load();
    match state.pending_txs.get_mut(key) {
        Some(pending) => pending.tx_hash = Some(hash),
        // Cleared underneath us (a concurrent `clear_pending_tx`); re-creating the
        // record from a hash alone would lose the nonce and fees it is built on.
        None => {
            warn!(logger = "TaskStore", route = self.label().as_str(), key, "No pending record to attach a tx hash to");
            return;
        }
    }
    self.save(&state);
}

