use alloy::primitives::{Address, U256};
use std::sync::{Arc, Mutex};
use crate::config::{Route, ValidatorConfig};
use crate::contracts::{IVeaInboxArbToEth, IVeaInboxArbToGnosis};
use crate::tasks::{send_or_replace, ClaimStore, Durability, TaskStore};

pub async fn execute(
    config: &ValidatorConfig,
    route: &Route,
    epoch: u64,
    claim_store: &Arc<Mutex<ClaimStore>>,
    task_store: &Arc<Mutex<TaskStore>>,
    wallet_address: Address,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let claim = claim_store.lock().unwrap().get_claim(epoch);

    // This write lands on Arbitrum, so the bar is batch inclusion, not the L2 `finalized`
    // tag: the snapshot is only as durable as the L1 batch carrying the block it is in.
    // Until then the sequencer could still reorder or drop it, and the dispatcher would
    // have retired the task with no `SnapshotSent` ever reaching the indexer - no relay,
    // and nothing to prove the challenge with on L1.
    let durability = Durability::ArbitrumBatchFinalized {
        l1_provider: config.ethereum_provider.clone(),
        sequencer_inbox: config.sequencer_inbox,
    };

    match route.name {
        "ARB_TO_ETH" => {
            let inbox = IVeaInboxArbToEth::new(route.inbox_address, route.inbox_provider.clone());
            send_or_replace(
                inbox.sendSnapshot(U256::from(epoch), claim),
                &route.inbox_provider,
                wallet_address,
                task_store,
                epoch,
                "sendSnapshot",
                route.name,
                &durability,
            ).await
        }
        "ARB_TO_GNOSIS" => {
            let inbox = IVeaInboxArbToGnosis::new(route.inbox_address, route.inbox_provider.clone());
            let gas_limit = U256::from(500000);
            send_or_replace(
                inbox.sendSnapshot(U256::from(epoch), gas_limit, claim),
                &route.inbox_provider,
                wallet_address,
                task_store,
                epoch,
                "sendSnapshot",
                route.name,
                &durability,
            ).await
        }
        _ => panic!("Unknown route: {}", route.name),
    }
}

